with current change
* `F(output, "module", () => Boolean(experiments.outputModule));` seems current behavior now so keep it as it is
*  change output.chunkFormat default value according to output.module and throw error if conflict with targetProperties
```js
	F(output, "chunkFormat", () => {
        // do tp and output.module conflict validation
		F(output, "chunkFormat", () => {
		if (tp) {
			const helpMessage = isAffectedByBrowserslist
				? "Make sure that your 'browserslist' includes only platforms that support these features or select an appropriate 'target' to allow selecting a chunk format by default. Alternatively specify the 'output.chunkFormat' directly."
				: "Select an appropriate 'target' to allow selecting one by default, or specify the 'output.chunkFormat' directly.";
			if (output.module) {
              // throw error if output.module conflict with tp
              if(!tp.dynamicImport) {
                 throw new Error(
					"For the selected environment is no default ESM chunk format available:\n" +
						"ESM exports can be chosen when 'import()' is available.\n" +
						`${
							helpMessage
						}`
				);
               return  'module';
              }		
			} else {
				if (tp.document) return "array-push";
				if (tp.require) return "commonjs";
				if (tp.nodeBuiltins) return "commonjs";
				if (tp.importScripts) return "array-push";
				throw new Error(
					"For the selected environment is no default script chunk format available:\n" +
						"JSONP Array push can be chosen when 'document' or 'importScripts' is available.\n" +
						`CommonJs exports can be chosen when 'require' or node builtins are available.\n${
							helpMessage
						}`
				);
			}
		}
		throw new Error(
			"Chunk format can't be selected by default when no target is specified"
		);
	});
	});
```

@hardfist In fact, we support `array-push` format for `module`. Also what we should do if developer don't have `Browserslist` or `target: "web"`? Currently we have:

```js
F(environment, "dynamicImport", () =>
		conditionallyOptimistic(
			/** @type {boolean | undefined} */ (tp && tp.dynamicImport),
			output.module
		)
	);
```

Our logic - if we don't have any information about `dynamicImport` we assume that it is supported

